/**
 * generated by stackra gen from the `@Env` fields of src/config/*.config.ts and runway.yaml
 * environments.<env>.vars — do not edit
 * Purpose: the public env: every `process.env.EXPO_PUBLIC_*` read as a literal so Expo can inline
 *          it, and the validated `MobileEnv` instance parsed once through its field rules with its
 *          defaults. A missing or malformed value fails at boot with a typed error; a value missing
 *          in some environment already failed `stackra validate` against runway.yaml `vars`.
 * Boundary: only `EXPO_PUBLIC_` names pass gen; a value never holds a secret. `createApp` layers
 *           `publicEnv` into every config class with an `@Env` field (the package overrides
 *           included) after construction; components read a class with `useConfig(X)`. The `env`
 *           instance is for generated code outside React (linking).
 * Runtime: react-native
 */
import { hydrateEnv } from "@stackra/config/env";
import { MobileEnv } from "#src/config/env.config";

/** Every public value the binary carries, by name; Expo inlines each literal read. */
export const publicEnv = {
  EXPO_PUBLIC_EAS_PROJECT_ID: process.env.EXPO_PUBLIC_EAS_PROJECT_ID,
  EXPO_PUBLIC_API_ORIGIN: process.env.EXPO_PUBLIC_API_ORIGIN,
  EXPO_PUBLIC_APP_ORIGIN: process.env.EXPO_PUBLIC_APP_ORIGIN,
  EXPO_PUBLIC_REALTIME_ORIGIN: process.env.EXPO_PUBLIC_REALTIME_ORIGIN,
  EXPO_PUBLIC_ZITADEL_ISSUER: process.env.EXPO_PUBLIC_ZITADEL_ISSUER,
  EXPO_PUBLIC_ZITADEL_CLIENT_ID: process.env.EXPO_PUBLIC_ZITADEL_CLIENT_ID,
  EXPO_PUBLIC_SENTRY_DSN: process.env.EXPO_PUBLIC_SENTRY_DSN,
  EXPO_PUBLIC_PUSH_PROVIDER: process.env.EXPO_PUBLIC_PUSH_PROVIDER,
  EXPO_PUBLIC_POSTHOG_KEY: process.env.EXPO_PUBLIC_POSTHOG_KEY,
} as const;

/** The parsed env contract (`stackra.config.ts` `env`). */
export const env: MobileEnv = hydrateEnv(MobileEnv, publicEnv);
